import Foundation
import Dispatch
import Matter

func testBaseSwitchInit() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)
    _ = MTRBaseClusterSwitch(device: baseDevice, endpointID: n(1), queue: DispatchQueue.global())
    _ = MTRBaseClusterSwitch(device: baseDevice, endpoint: 1, queue: DispatchQueue.global())
}

func testBaseSwitchClassCache() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)
    MTRBaseClusterSwitch.readAttributeAcceptedCommandList(withAttributeCache: MTRAttributeCacheContainer(), endpoint: n(1), queue: DispatchQueue.global(), completionHandler: { _, err in mtrExpectInvalidState(err) })
